-- ============================================================================
-- V8 - Technical Master field dictionary (ONEMEP-29, per official PTMS xlsx)
--
-- ADDITIVE (does not touch V6 tables). The per-project Technical Master sheet is
-- driven by the project category's series_code (1 Commercial .. 10 Mixed-Use,
-- seeded in V4). tm_field = the field catalog (200 fields / 27 sections);
-- tm_field_category = which category series_code each field applies to;
-- project_technical_field_value = the filled values per project.
-- No dropdowns exist in the sheet, so data_type is NUMBER or TEXT only.
-- ============================================================================

CREATE TABLE tm_field (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    section       VARCHAR(80)  NOT NULL,
    section_order INT          NOT NULL,
    label         VARCHAR(200) NOT NULL,
    field_key     VARCHAR(160) NOT NULL,
    unit          VARCHAR(60),
    data_type     VARCHAR(10)  NOT NULL,
    feeds         VARCHAR(10)  NOT NULL,
    core          BOOLEAN      NOT NULL DEFAULT FALSE,
    notes         VARCHAR(300),
    field_order   INT          NOT NULL,
    CONSTRAINT uq_tm_field_key UNIQUE (field_key),
    CONSTRAINT ck_tm_field_dtype CHECK (data_type IN ('NUMBER','TEXT')),
    CONSTRAINT ck_tm_field_feeds CHECK (feeds IN ('YES','REF'))
);

CREATE TABLE tm_field_category (
    field_id    BIGINT NOT NULL,
    series_code INT    NOT NULL,
    CONSTRAINT pk_tm_field_category PRIMARY KEY (field_id, series_code),
    CONSTRAINT fk_tm_field_category_field FOREIGN KEY (field_id) REFERENCES tm_field (id)
);
CREATE INDEX idx_tm_field_category_series ON tm_field_category (series_code);

CREATE TABLE project_technical_field_value (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    technical_master_id BIGINT       NOT NULL,
    field_key           VARCHAR(160) NOT NULL,
    value               VARCHAR(2000),
    created_date        TIMESTAMP    NOT NULL,
    created_by          BIGINT,
    updated_by          BIGINT,
    updated_date        TIMESTAMP,
    CONSTRAINT fk_tm_value_master FOREIGN KEY (technical_master_id) REFERENCES project_technical_master (id),
    CONSTRAINT uq_tm_value UNIQUE (technical_master_id, field_key)
);
CREATE INDEX idx_tm_value_master ON project_technical_field_value (technical_master_id);

